function App() {
  const colors = {
    success: { bg: '#dcfce7', fg: '#166534' },
    warning: { bg: '#fef9c3', fg: '#854d0e' },
    error: { bg: '#fee2e2', fg: '#991b1b' }
  };
  const Badge = ({ status, children }) => {
    const c = colors[status] || colors.success;
    const className = 'badge badge-' + status;
    return (
      <span className={className} style={{ background: c.bg, color: c.fg, padding: '2px 10px', borderRadius: 999, fontSize: 13, marginRight: 8 }}>
        {children}
      </span>
    );
  };
  return (
    <div style={{ fontFamily: 'system-ui', padding: 16 }}>
      <Badge status="success">Active</Badge>
      <Badge status="warning">Pending</Badge>
      <Badge status="error">Failed</Badge>
    </div>
  );
}
